<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$counts=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'active'=>(int)$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Pending'")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status IN ('Paid','Processing','Shipped','Completed')")->fetchColumn()];$latest=$pdo->query('SELECT order_number,customer_name,total,status,created_at FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();admin_header('Overview');?><div class="stats-grid"><?php foreach(['Products'=>$counts['products'],'Active products'=>$counts['active'],'Orders'=>$counts['orders'],'Pending orders'=>$counts['pending'],'Revenue'=>money($counts['revenue'])] as $k=>$v):?><div class="stat-card"><span><?=e($k)?></span><b><?=e((string)$v)?></b></div><?php endforeach;?></div><section class="admin-panel"><h2>Latest orders</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th></th></tr><?php foreach($latest as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['customer_name'])?></td><td><?=money((float)$o['total'])?></td><td><?=e($o['status'])?></td><td><a href="order-detail.php?id=<?=(int)$o['order_number']?>">View</a></td></tr><?php endforeach;?></table></div></section><?php admin_footer(); ?>
